62: function instancedBoxes(parent, name, size, positions, material) {
63:   const mesh = new THREE.InstancedMesh(new THREE.BoxGeometry(...size), material, positions.length);
64:   const transform = new THREE.Object3D();
65:   positions.forEach((position, index) => {
66:     transform.position.set(...position);
67:     transform.updateMatrix();
68:     mesh.setMatrixAt(index, transform.matrix);
69:   });
70:   mesh.name = name;
71:   mesh.instanceMatrix.needsUpdate = true;
72:   mesh.castShadow = false;
73:   mesh.receiveShadow = true;
74:   parent.add(mesh);
75:   return mesh;
