80:   const d = direction * length;
81:   const vertices = new Float32Array([
82:     -width/2,0,0, width/2,0,0, -width/2,rise,d,
83:     width/2,0,0, width/2,rise,d, -width/2,rise,d,
84:     -width/2,0,0, -width/2,rise,d, width/2,0,0,
85:     width/2,0,0, -width/2,rise,d, width/2,rise,d
86:   ]);
87:   const geo = new THREE.BufferGeometry(); geo.setAttribute('position', new THREE.BufferAttribute(vertices,3)); geo.computeVertexNormals();
88:   const surface = new THREE.Mesh(geo, color); surface.material.side = THREE.DoubleSide; surface.castShadow = true; surface.receiveShadow = true; group.add(surface);
89:   // Lip strip at the high end
90:   box(group, `${name}-lip`, [width,.12,.16], [0,rise,d], edgePaint, [0,0,0], false);
91:   return group;
